  The handler:
  ```go
  func (h *Handlers) BatchInfer(w http.ResponseWriter, r *http.Request) {
      var req struct {
          Requests []serving.InferenceRequest `json:"requests"`
          Strategy string `json:"strategy"`
      }
      // decode
      if req.Requests == nil || len(req.Requests) == 0 {
          writeError(400, "requests array is required")
          return
      }
      if req.Strategy == "" {
          req.Strategy = "independent"
      }
      if req.Strategy != "independent" && req.Strategy != "stop_on_error" {
          writeError(400, "invalid strategy")
          return
      }
      start := time.Now()
      results := make([]map[string]interface{}, 0, len(req.Requests))
      succeeded, failed, skipped := 0, 0, 0
      stop := false
      for i, infReq := range req.Requests {
          if stop {
              results = append(results, map[string]interface{}{"model_name": infReq.ModelName, "status": "skipped"})
              skipped++
              continue
          }
          resp, err := h.Serving.Infer(&infReq)
          if err != nil {
              results = append(results, map[string]interface{}{"model_name": infReq.ModelName, "error": err.Error()})
              failed++
              if req.Strategy == "stop_on_error" {
                  stop = true
              }
              continue
          }
          results = append(results, map[string]interface{}{
              "model_name": resp.ModelName,
              "version": resp.Version,
              "predictions": resp.Predictions,
              "latency_ms": resp.LatencyMs,
          })
          succeeded++
      }
      totalLatency := float64(time.Since(start).Microseconds()) / 1000.0
      summary := map[string]interface{}{"total": len(req.Requests), "succeeded": succeeded, "failed": failed}
      if req.Strategy == "stop_on_error" {
          summary["skipped"] = skipped
      }
      writeJSON(200, map[string]interface{}{"results": results, "total_latency_ms": totalLatency, "summary": summary})
  }
  ```
