// StepExecutor is the function signature for executing a pipeline step.
type StepExecutor func(config, input map[string]interface{}) (map[string]interface{}, error)

// NewEngine creates a pipeline engine with built-in step executors.
func NewEngine() *Engine {
	e := &Engine{
		stepExecutors: make(map[StepType]StepExecutor),
