// Execute runs a pipeline with the given initial input data.
func (e *Engine) Execute(p *Pipeline, initialInput map[string]interface{}) (*PipelineResult, error) {
	ordered, err := topologicalSort(p.Steps)
	if err != nil {
		return nil, fmt.Errorf("dependency resolution failed: %w", err)
