// topologicalSort orders steps so that dependencies are executed first.
// Returns an error if a cycle is detected.
func topologicalSort(steps []*Step) ([]*Step, error) {
	stepMap := make(map[string]*Step)
	inDegree := make(map[string]int)

	for _, s := range steps {
		stepMap[s.Name] = s
		inDegree[s.Name] = 0
	}

	// Build in-degree counts
	for _, s := range steps {
		for _, dep := range s.Dependencies {
			if _, ok := stepMap[dep]; !ok {
				return nil, fmt.Errorf("step %q depends on unknown step %q", s.Name, dep)
			}
			inDegree[s.Name]++
		}
	}

	// Initialize queue with steps that have no dependencies
	queue := make([]*Step, 0)
	for _, s := range steps {
		if inDegree[s.Name] == 0 {
			queue = append(queue, s)
		}
	}

	// Process steps in topological order
	ordered := make([]*Step, 0, len(steps))
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		ordered = append(ordered, current)

		// Find steps that depend on current
		for _, s := range steps {
			for _, dep := range s.Dependencies {
				if dep == current.Name {
					inDegree[s.Name]--
					if inDegree[s.Name] == 0 {
						queue = append(queue, s)
					}
				}
			}
		}
	}

	if len(ordered) != len(steps) {
		return nil, fmt.Errorf("cycle detected in pipeline dependencies")
	}

	return ordered, nil
}

// mergeDependencyOutputs concatenates the "data" arrays from all dependency outputs into a single input.
func mergeDependencyOutputs(deps []string, outputs map[string]map[string]interface{}) map[string]interface{} {
	merged := make([]interface{}, 0)
	for _, dep := range deps {
		out, ok := outputs[dep]
		if !ok {
			continue
		}
		switch data := out["data"].(type) {
		case []interface{}:
			merged = append(merged, data...)
		case []float64:
			for _, v := range data {
				merged = append(merged, v)
			}
		}
	}
	return map[string]interface{}{"data": merged}
}

func computeTransitiveDependencies(steps []*Step) map[string]map[string]bool {
	stepMap := make(map[string]*Step)
	for _, s := range steps {
		stepMap[s.Name] = s
	}

	result := make(map[string]map[string]bool)
	var visit func(s *Step) map[string]bool

	visit = func(s *Step) map[string]bool {
		if deps, ok := result[s.Name]; ok {
			return deps
		}
		deps := make(map[string]bool)
		for _, dep := range s.Dependencies {
			deps[dep] = true
			if depStep, ok := stepMap[dep]; ok {
				for d := range visit(depStep) {
					deps[d] = true
				}
			}
		}
		result[s.Name] = deps
		return deps
	}

	for _, s := range steps {
		visit(s)
	}
	return result
}

func resolveVariables(config map[string]interface{}, variables map[string]float64, setter map[string]string, depSet map[string]bool) (map[string]interface{}, error) {
	if len(variables) == 0 {
		return config, nil
	}

	resolved := make(map[string]interface{}, len(config))
	for k, v := range config {
		if s, ok := v.(string); ok {
			if strings.HasPrefix(s, "${") && strings.HasSuffix(s, "}") {
