				val, ok := variables[varName]
				if !ok {
					return nil, fmt.Errorf("undefined variable")
				}
				setterStep, ok := setter[varName]
				if !ok || !depSet[setterStep] {
					return nil, fmt.Errorf("variable not in dependency chain")
				}
				resolved[k] = val
				continue
			}
		}
		resolved[k] = v
	}
	return resolved, nil
}

func applyOutputTransform(output map[string]interface{}, config map[string]interface{}, transform string) (map[string]interface{}, error) {
	data, ok := output["data"]
	if !ok {
		return output, nil
	}

	var arr []interface{}
	switch d := data.(type) {
	case []interface{}:
		arr = d
	case []float64:
		arr = make([]interface{}, len(d))
		for i, v := range d {
			arr[i] = v
		}
	default:
