		arr = make([]interface{}, len(vals))
		for i, v := range vals {
			arr[i] = v
		}

	case "sort_desc":
		vals, err := toFloatSlice(arr)
		if err != nil {
			return nil, err
		}
		sort.Sort(sort.Reverse(sort.Float64Slice(vals)))
		arr = make([]interface{}, len(vals))
		for i, v := range vals {
			arr[i] = v
		}

	case "unique":
		seen := make(map[float64]bool)
		unique := make([]interface{}, 0, len(arr))
		for _, v := range arr {
			val, err := toFloat(v)
			if err != nil {
				return nil, fmt.Errorf("output transform unique: non-numeric value: %w", err)
			}
			if !seen[val] {
				seen[val] = true
				unique = append(unique, v)
			}
		}
		arr = unique

