package api

import (
	"encoding/json"
	"fmt"
	"net/http"
	"regexp"
	"sort"
	"strings"
	"sync"
	"time"

	"gomlops/internal/pipeline"
)

type TemplateParameter struct {
	Name    string      `json:"name"`
	Type    string      `json:"type"`
	Default interface{} `json:"default,omitempty"`
}

type Template struct {
	Name        string              `json:"name"`
	Description string              `json:"description"`
	Parameters []TemplateParameter `json:"parameters"`
	Pipeline    *pipeline.Pipeline `json:"pipeline"`
	CreatedAt   time.Time           `json:"created_at"`
	UpdatedAt   *time.Time         `json:"updated_at"`
}

type TemplateStore struct {
	mu        sync.RWMutex
	templates map[string]*Template
}

func NewTemplateStore() *TemplateStore {
	return &TemplateStore{templates: make(map[string]*Template)}
}

var templateNameRe = regexp.MustCompile(`^[a-zA-Z0-9_-]+$`)

func validateTemplateName(name string) bool {
	return len(name) > 0 && len(name) <= 64 && templateNameRe.MatchString(name)
}

func (s *TemplateStore) Get(name string) (*Template, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	t, ok := s.templates[name]
	return t, ok
}

func (s *TemplateStore) List(sortBy string) []*Template {
	s.mu.RLock()
	defer s.mu.RUnlock()
	result := make([]*Template, 0, len(s.templates))
	for _, t := range s.templates {
		result = append(result, t)
	}
	if sortBy == "created_at" {
		sort.Slice(result, func(i, j int) bool {
			return result[i].CreatedAt.Before(result[j].CreatedAt)
		})
	} else {
		sort.Slice(result, func(i, j int) bool {
			return result[i].Name < result[j].Name
		})
	}
	return result
}

func (s *TemplateStore) Create(t *Template) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.templates[t.Name]; exists {
		return fmt.Errorf("template %q already exists", t.Name)
	}
	t.CreatedAt = time.Now()
	t.UpdatedAt = nil
	s.templates[t.Name] = t
	return nil
}

func (s *TemplateStore) Update(t *Template) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.templates[t.Name]; !exists {
		return fmt.Errorf("template %q not found", t.Name)
	}
	now := time.Now()
	t.UpdatedAt = &now
	s.templates[t.Name] = t
	return nil
}

func (s *TemplateStore) Delete(name string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.templates[name]; !exists {
		return fmt.Errorf("template %q not found", name)
	}
	delete(s.templates, name)
	return nil
}

func (h *Handlers) CreateTemplate(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name        string              `json:"name"`
		Description string              `json:"description"`
		Parameters []TemplateParameter `json:"parameters"`
		Pipeline    *pipeline.Pipeline `json:"pipeline"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body: %v", err)
		return
	}
	if !validateTemplateName(req.Name) {
		writeError(w, http.StatusBadRequest, "invalid template name")
		return
	}
	if req.Pipeline == nil || len(req.Pipeline.Steps) == 0 {
		writeError(w, http.StatusBadRequest, "pipeline with at least one step is required")
		return
	}
	params := req.Parameters
	if params == nil {
		params = []TemplateParameter{}
	}
	if err := validateParameters(params); err != nil {
		writeError(w, http.StatusBadRequest, "%v", err)
		return
	}
	tmpl := &Template{
		Name:        req.Name,
		Description: req.Description,
		Parameters:  params,
		Pipeline:    req.Pipeline,
	}
	if err := h.Templates.Create(tmpl); err != nil {
		writeError(w, http.StatusConflict, "%v", err)
		return
	}
	writeJSON(w, http.StatusCreated, templateResponse(tmpl))
}

func (h *Handlers) ListTemplates(w http.ResponseWriter, r *http.Request) {
	sortBy := r.URL.Query().Get("sort")
	writeJSON(w, http.StatusOK, templateListResponse(h.Templates.List(sortBy)))
}

func (h *Handlers) GetTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	tmpl, ok := h.Templates.Get(name)
	if !ok {
		writeError(w, http.StatusNotFound, "template %q not found", name)
		return
	}
	writeJSON(w, http.StatusOK, templateResponse(tmpl))
}

func (h *Handlers) UpdateTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	tmpl, ok := h.Templates.Get(name)
	if !ok {
		writeError(w, http.StatusNotFound, "template %q not found", name)
		return
	}
	var req struct {
		Description *string              `json:"description"`
		Parameters *[]TemplateParameter `json:"parameters"`
		Pipeline   *pipeline.Pipeline   `json:"pipeline"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body: %v", err)
		return
	}
	updated := &Template{
		Name:        tmpl.Name,
		Description: tmpl.Description,
		Parameters:  tmpl.Parameters,
		Pipeline:    tmpl.Pipeline,
		CreatedAt:   tmpl.CreatedAt,
	}
	if req.Description != nil {
		updated.Description = *req.Description
	}
	if req.Parameters != nil {
		if err := validateParameters(*req.Parameters); err != nil {
			writeError(w, http.StatusBadRequest, "%v", err)
			return
		}
		updated.Parameters = *req.Parameters
	}
	if req.Pipeline != nil {
		if len(req.Pipeline.Steps) == 0 {
			writeError(w, http.StatusBadRequest, "pipeline with at least one step is required")
			return
		}
		updated.Pipeline = req.Pipeline
	}
	if err := h.Templates.Update(updated); err != nil {
		writeError(w, http.StatusNotFound, "%v", err)
		return
	}
	writeJSON(w, http.StatusOK, templateResponse(updated))
}

func (h *Handlers) DeleteTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	if err := h.Templates.Delete(name); err != nil {
		writeError(w, http.StatusNotFound, "%v", err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "deleted"})
}

func (h *Handlers) ExecuteTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	tmpl, ok := h.Templates.Get(name)
	if !ok {
		writeError(w, http.StatusNotFound, "template %q not found", name)
		return
	}
	var req struct {
		Input  map[string]interface{} `json:"input"`
		Params map[string]interface{} `json:"params"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body: %v", err)
		return
	}
	p, err := substituteParameters(tmpl, req.Params)
	if err != nil {
		writeError(w, http.StatusBadRequest, "%v", err)
		return
	}
	if req.Input == nil {
		req.Input = make(map[string]interface{})
	}
	result, err := h.Pipeline.Execute(p, req.Input)
	if err != nil {
		writeError(w, http.StatusBadRequest, "%v", err)
		return
	}
	writeJSON(w, http.StatusOK, result)
}

func validateParameters(params []TemplateParameter) error {
	names := make(map[string]bool)
	for _, p := range params {
		if p.Name == "" {
			return fmt.Errorf("parameter name is required")
		}
		if names[p.Name] {
			return fmt.Errorf("duplicate parameter name %q", p.Name)
		}
		names[p.Name] = true
		if p.Type != "number" && p.Type != "string" {
			return fmt.Errorf("parameter %q type must be number or string", p.Name)
		}
		if p.Default != nil {
			switch p.Type {
			case "number":
				if _, ok := toFloat64(p.Default); !ok {
					return fmt.Errorf("parameter %q default must be a number", p.Name)
				}
			case "string":
				if _, ok := p.Default.(string); !ok {
					return fmt.Errorf("parameter %q default must be a string", p.Name)
				}
			}
		}
	}
	return nil
}

func toFloat64(v interface{}) (float64, bool) {
	switch val := v.(type) {
	case float64:
		return val, true
	case int:
		return float64(val), true
	case int64:
		return float64(val), true
	}
	return 0, false
}

func substituteParameters(tmpl *Template, params map[string]interface{}) (*pipeline.Pipeline, error) {
	declared := make(map[string]TemplateParameter)
	for _, p := range tmpl.Parameters {
		declared[p.Name] = p
	}
	for name := range params {
		if _, ok := declared[name]; !ok {
			return nil, fmt.Errorf("unknown parameter %q", name)
		}
	}
	resolved := make(map[string]interface{})
	for name, p := range declared {
		if val, ok := params[name]; ok {
			if err := validateParamValue(p, val); err != nil {
				return nil, err
			}
			resolved[name] = val
		} else if p.Default != nil {
			resolved[name] = p.Default
		} else {
			return nil, fmt.Errorf("missing required parameter %q", name)
		}
	}
	data, err := json.Marshal(tmpl.Pipeline)
	if err != nil {
		return nil, err
	}
	var p pipeline.Pipeline
	if err := json.Unmarshal(data, &p); err != nil {
		return nil, err
	}
	for _, step := range p.Steps {
		if step.Config != nil {
			for k, v := range step.Config {
				if s, ok := v.(string); ok {
					if strings.HasPrefix(s, "${param.") && strings.HasSuffix(s, "}") {
						paramName := s[8 : len(s)-1]
						val, ok := resolved[paramName]
						if !ok {
							return nil, fmt.Errorf("unknown parameter %q", paramName)
						}
						step.Config[k] = val
					}
				}
			}
		}
	}
	return &p, nil
}

func validateParamValue(p TemplateParameter, val interface{}) error {
	switch p.Type {
	case "number":
		if _, ok := toFloat64(val); !ok {
			return fmt.Errorf("parameter %q must be a number", p.Name)
			}
	case "string":
		if _, ok := val.(string); !ok {
			return fmt.Errorf("parameter %q must be a string", p.Name)
			}
	}
	return nil
}

func templateResponse(t *Template) map[string]interface{} {
	params := t.Parameters
	if len(params) == 0 {
		params = nil
	}
	return map[string]interface{}{
		"name":        t.Name,
		"description": t.Description,
		"parameters":  params,
		"pipeline":    t.Pipeline,
		"created_at":  t.CreatedAt,
		"updated_at":  t.UpdatedAt,
	}
}

func templateListResponse(templates []*Template) []map[string]interface{} {
	result := make([]map[string]interface{}, 0, len(templates))
	for _, t := range templates {
		result = append(result, templateResponse(t))
	}
	return result
}
