type batchRequest struct {
	Requests []serving.InferenceRequest `json:"requests"`
	Strategy string                     `json:"strategy"`
}

func (h *Handlers) BatchInfer(w http.ResponseWriter, r *http.Request) {
	var req batchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body: %v", err)
		return
	}
	if len(req.Requests) == 0 {
		writeError(w, http.StatusBadRequest, "requests array is required and cannot be empty")
		return
	}
	strategy := req.Strategy
	if strategy == "" {
		strategy = "independent"
	}
	if strategy != "independent" && strategy != "stop_on_error" {
		writeError(w, http.StatusBadRequest, "invalid strategy %q", strategy)
		return
	}

	start := time.Now()
	results := make([]map[string]interface{}, 0, len(req.Requests))
	succeeded := 0
	failed := 0
	skipped := 0
	stop := false

	for i, ir := range req.Requests {
		if stop {
			results = append(results, map[string]interface{}{
				"model_name": ir.ModelName,
				"status":    "skipped",
			})
			skipped++
			continue
		}

		if ir.ModelName == "" {
			results = append(results, map[string]interface{}{
				"model_name": ir.ModelName,
				"error":      "model_name is required",
			})
			failed++
			if strategy == "stop_on_error" {
				stop = true
			}
			continue
		}

		resp, err := h.Serving.Infer(&ir)
		if err != nil {
			results = append(results, map[string]interface{}{
				"model_name": ir.ModelName,
				"error":      err.Error(),
			})
			failed++
			if strategy == "stop_on_error" {
				stop = true
			}
			continue
		}

		results = append(results, map[string]interface{}{
			"model_name":   resp.ModelName,
			"version":      resp.Version,
			"predictions":  resp.Predictions,
			"latency_ms":   resp.LatencyMs,
		})
		succeeded++
		_ = i
	}

	summary := map[string]int{
		"total":     len(req.Requests),
		"succeeded": succeeded,
		"failed":    failed,
	}
	if strategy == "stop_on_error" {
		summary["skipped"] = skipped
	}

	writeJSON(w, http.StatusOK, map[string]interface{}{
		"results":          results,
		"total_latency_ms": float64(time.Since(start).Microseconds()) / 1000.0,
		"summary":          summary,
	})
}
